def simulate_cycle(grid):
    """
    Simulates one growth/mutation cycle on a 4x4 grid.
    Returns the next grid state and a boolean indicating if any change occurred.
    """
    N = 4
    current_grid = np.array(grid)

    # Sets to track mandated changes based on current state
    must_be_one = set()
    cell_changes = {} # Stores (r, c) -> new_value if Rule 2 applies

    changed_in_cycle = False

    # Iterate over all 3x3 = 9 possible top-left corners (i, j) of 2x2 patches
    for i in range(N - 1):
        for j in range(N - 1):
            patch = current_grid[i:i+2, j:j+2]
            infected_count = np.sum(patch)

            if infected_count == 3:
                # Rule 1: Spread (3 infected -> last sterile gets infected)
                sterile_cells = []
                for r_offset in range(2):
                    for c_offset in range(2):
                        r, c = i + r_offset, j + c_offset
                        if current_grid[r, c] == 0:
                            sterile_cells.append((r, c))

                # There must be exactly one sterile cell if sum is 3
                if sterile_cells:
                    r_new, c_new = sterile_cells[0]
                    if current_grid[r_new, c_new] == 0:
                        must_be_one.add((r_new, c_new))

            elif infected_count == 2:
                # Rule 2: Mutation (2 infected -> flip entire 2x2 patch)
                for r_offset in range(2):
                    for c_offset in range(2):
                        r, c = i + r_offset, j + c_offset

                        old_value = current_grid[r, c]
                        new_value = 1 - old_value

                        if new_value != old_value:
                            # Record the change based on Rule 2
                            cell_changes[(r, c)] = new_value
                            changed_in_cycle = True

    # Construct the next grid state
    next_grid = current_grid.copy()

    # Apply Rule 1 mandates first (highest priority)
    for r, c in must_be_one:
        if current_grid[r, c] == 0: # Only track actual changes
            next_grid[r, c] = 1
            changed_in_cycle = True

    # Apply Rule 2 changes, unless already forced to 1 by Rule 1
    for (r, c), new_value in cell_changes.items():
        # Rule 1 mandates take precedence over Rule 2 flips
        if (r, c) not in must_be_one:
            next_grid[r, c] = new_value
            changed_in_cycle = True

    return next_grid.tolist(), changed_in_cycle

