def simulate_2x2(initial_k):
    """
    Simulates the evolution of a 2x2 grid starting with k infected cells.
    The grid is represented as a list of 4 cells (0 or 1).
    Since the grid is 2x2, the entire grid is the only 2x2 block.
    """
    if initial_k == 4:
        return "FULL", []
    if initial_k == 0:
        return "STALLED", [initial_k]

    # Start with a state matching initial_k (e.g., [1, 1, 0, 0] for k=2)
    state = [1] * initial_k + [0] * (4 - initial_k)
    history = []
    max_steps = 10 # Since the system is small, we expect quick convergence or cycle detection

    for step in range(max_steps):
        current_k = sum(state)
        history.append(current_k)

        next_state = list(state)
        rule_applied = False

        if current_k == 3:
            # Rule 1: S=3, find the single sterile cell (0) and flip it to 1
            for i in range(4):
                if state[i] == 0:
                    next_state[i] = 1
                    rule_applied = True
                    break

        elif current_k == 2:
            # Rule 2: S=2, flip all cells
            for i in range(4):
                next_state[i] = 1 - state[i]
            rule_applied = True

        elif current_k == 1 or current_k == 4:
            # No rules apply or it's already full
            pass

        if not rule_applied and current_k != 4:
            return "STALLED", history

        if sum(next_state) == 4:
            return "FULL", history + [4]

        state = next_state

    # If simulation runs out of steps (cycle detected or slow approach)
    return "CYCLE/STALLED", history

