def apply_rules(grid):
    N = grid.shape[0]
    new_grid = grid.copy()

    # Track changes to apply simultaneously
    changes = {} 

    # Iterate over all possible 2x2 blocks
    for i in range(N - 1):
        for j in range(N - 1):
            # Extract the 2x2 block
            block = grid[i:i+2, j:j+2]
            S = np.sum(block)

            if S == 3:
                # Rule 1: One sterile cell gets infected
                sterile_coords = []
                for r in range(2):
                    for c in range(2):
                        if block[r, c] == 0:
                            sterile_coords.append((i + r, j + c))

                if sterile_coords:
                    r, c = sterile_coords[0]
                    changes[(r, c)] = 1 # Infect

            elif S == 2:
                # Rule 2: Mutation (flip states)
                for r in range(2):
                    for c in range(2):
                        coords = (i + r, j + c)
                        # We apply the flip change to the changes dictionary
                        # Flip means state changes by 1 - 2*state_original
                        # If original is 0, new is 1 (+1). If original is 1, new is 0 (-1).
                        if coords not in changes:
                            changes[coords] = 0

                        original_state = grid[coords]
                        # The change applied must result in 1 - original_state
                        new_state = 1 - original_state
                        changes[coords] = new_state

    # Apply all collected changes simultaneously
    for (r, c), new_state in changes.items():
        new_grid[r, c] = new_state

    return new_grid

def simulate_spread(initial_grid, max_steps=1000):
    grid = initial_grid.copy()
    for step in range(max_steps):
        next_grid = apply_rules(grid)

        if np.array_equal(next_grid, grid):
            # Stabilized
            return next_grid, step

        grid = next_grid

    # Reached max steps
    return grid, max_steps

